mapper.select:
SELECT f.order_id,f.status,f.tracking_no,f.provider,f.blocked,f.version FROM fulfillment_record f JOIN order_record o ON o.tenant_id=f.tenant_id AND o.order_id=f.order_id WHERE f.tenant_id=#{tenant}  AND f.order_id>#{after}
    AND (LOCATE(#{filter.q},f.order_id)>0 OR LOCATE(#{filter.q},f.tracking_no)>0 OR LOCATE(#{filter.q},f.provider)>0)
    AND f.status=#{filter.status} ORDER BY f.order_id LIMIT #{limit}
